@register.simple_tag()
def field(labeltag, form, field, cls=''):
    rend = ''
    if cls:
        rend += '<div class="%s">' % cls
    rend += '<%s %s>' % (labeltag, field.label_tag())
    rend += "%s %s" % (form[field.name], form.errors[field.name])
    rend += '</%s>' % labeltag
