@register.tag()
def render_model(parser, token):
    """
    With 3 params:
      - object instance
      - model field name
      - (optionnaly) default content if object Instance or field value is None or empty
    """
    # Chop off the tag name
    token = token.contents.split()
    if len(token) < 3:
        raise ValueError('render_model node requires at least three arguments ')

    class RenderModelNode(NodeTransformer):
        def __init__(self, nodelist):
            self.nodelist = nodelist

        def visit_Variable(self, node):
            lookuptuple = Variable(node.var).resolve
            if lookuptuple is None or (lookuptuple() is None or lookuptuple() == ''):
                if len(token) == 5:
                    node = parser.parse([token[4]])
                    parser.stream.next
                    return node
                return parser.parse(nodelist)
            nodelist = parser.parse(nodelist)
            return node

    try:
        objvar, fieldname = token[1], token[2]
        defaulttoken = token[3].strip('"')
        endtoken = token[-1].strip('"')
        if endtoken != 'endrendermodel':
            raise ValueError('endtoken should be endrendermodel')
        nodelist = parser.parse((objvar, fieldname, defaulttoken, endtoken))
        return RenderModelNode(nodelist)
    except:
        raise ValueError('Invalid token in render_model node')


class RenderModelNode(Node):
    def __init__(self, nodeachter):
        self.nodelist = nodeachter

    def render(self, context):
        lookuptuple = Variable(self.nodelist)
        return lookuptuple.resolve(context)

