from django import template
import urlparse

register = template.Library()


def _make_url(relative_url, site_url):
    """
    Accepts a relative URL and a site URL and returns the two joined
    """
    site = urlparse.urlparse(site_url)
    relative = urlparse.urlparse(relative_url)
    # If the relative URL has no protocol or host, assume it's the same
    if not relative.scheme or not relative.netloc:
        # If the relative URL has no scheme, use the one from the site URL
        if not relative.scheme:
            relative = urlparse.ParseResult(site.scheme) + relative[1:]
        # If the relative URL has no host, use the one from the site URL
        if not relative.netloc:
            relative = urlparse.ParseResult(
                relative[:3] + (site.netloc,) + relative[4:]
            )
    return urlparse.urlunparse(relative)


@register.simple_tag(takes_context=True)
def absolute_url(context, name):
    """
    returns the absolute version of a relative URL
    """
    root = context['request'].site.root
    relative_url = context[name]
    if not relative_url:
        return
    return _make_url(relative_url, root.url)


@register.filter
def absolute(value, site_url):
    """
    returns the absolute version of a relative URL
    """
    if not value:
        return
    return _make_url(value, site_url)


