  return boundfield.field.__class__.__name__

@register.filter
def fieldclass(boundfield):
  classes = set()
  classes.add('control')

  if isinstance(boundfield.field, template.defaultfilters.stringfilter):
    classes.add('uneditable-input')

  if boundfield.errors:
    classes.add('input-error')

  if boundfield.is_checkbox:
    classes.add('checkbox')
  elif boundfield.is_file:
    classes.add('file')
  elif 'radio' in boundfield.widget.attrs.get('class', ''):
    classes.add('radio')
  elif fieldtype(boundfield) == 'DateField':
    classes.add('date')
  elif fieldtype(boundfield) == 'TimeField':
    classes.add('time')
  elif fieldtype(boundfield) == 'DateTimeField':
    classes.add('datetime')
  elif fieldtype(boundfield) == 'PhoneNumberField':
    classes.add('phone')
  elif fieldtype(boundfield) == 'InternationalPhoneNumberField':
    classes.add('international-phone')
  elif fieldtype(boundfield) == 'URLField':
    classes.add('url')
  elif fieldtype(boundfield) == 'EmailField':
    classes.add('email')
  elif fieldtype(boundfield) == 'IntegerField':
    classes.add('integer')
  elif fieldtype(boundfield) == 'DecimalField':
    classes.add('decimal')
  elif fieldtype(boundfield) == 'PositiveIntegerField':
    classes.add('positive-integer')
  elif fieldtype(boundfield) == 'DurationField':
    classes.add('duration')
  elif fieldtype(boundfield) == 'ArrayField':
    classes.add('array')

  return " ".join(classes)

