register = template.Library()

@register.simple_tag(takes_context=True)
def active(context, pattern):
    """
    Returns "active" if the input pattern
    matches the current request path.

    Usage:

    <li {% active 'blog:list' %}>Blog</li>

    """
    request = context['request']
    current_url = request.resolver_match.url_name
    current_app = getattr(request.resolver_match, 'app_name', None)
    if current_url and current_app:
        current_url = '%s:%s' % (current_app, current_url)
    if isinstance(pattern, tuple):
        return mark_safe('active') if current_url in pattern else ''
    elif pattern == current_url:
        return mark_safe('active')
    return ''

@register.tag
def el(context, token):
    """
    If its argument (enclosed in quotes) begins with
    a plus ('+'), get the named template, layout or fragment.

    If the argument begins with a dot ('.'),
    treat the rest as a path to a fragment in the
    layout.

    Otherwise, treat the rest of the argument as
    the URL of a view.

    We use `em` because `if` is a reserved word in Django templates.

    Note that `el` has to be used like a tag -
    you can't assign its result to a variable.

    Usage:

    Try to find a template named "comment/blog_post.html":
    {% el +utils:comment/blog_post.html +% counter = 2 %}

    Load the fragment named "paginator" from the base layout:
    {% el .paginator %}

    Show the related posts if there are any:
    {% el +blog:detail/related.html +% post = related %}

    """
    nodelist = []
    input_arg = token.split_contents()[1]

    if len(input_arg) < 2:
        raise template.TemplateSyntaxError, "el tag needs an argument"

    if input_arg[0] == '+':
        if input_arg[-1] == '+':
            # attempt to load a template
            pos = input_arg.index(':')
            if pos >= 0:
                path = input_arg[pos+len(":"):-1]
            else:
                path = input_arg[1:-1]
            source = get_template(path).template.source
        else:
            source = input_arg[1:-3]
    elif input_arg[0] == '.':
        source = context.layout.get_fragment(input_arg[1:])
    else:
        # bypass the renderer and get the URL directly from the request
        source = get_template("404.html").template.source

    return template.Template(source)

@register.tag
def loop(context, token):
    """
    Takes no more than two arguments:

    1. A space-delimited list of comma-separated tuples
    2. A block which is repeated for every element
       in the list.

    Each element is assigned to the variable named
    in the first position of the tuple, and if
    the second position is not specified,
    it defaults to "value".

    Usage:

    {% loop colors:"red,green,blue" %}
    <div style="background: {{ value }}">{{ value }}</div>
    {% endloop %}

    """
    args = token.split_contents()
    if len(args) < 2:
        raise template.TemplateSyntaxError, "el tag needs an argument"

    definitions = {}
    for item in args[1:]:
        try:
            name, items = item.split(':', 1)
            names = names.split(',')
            for n in names:
                definitions[n] = items
        except ValueError:
            name = args[1]
            items = args[2]
            definitions[name] = items

    nodelist = []

