@register.simple_tag
def addget(url, *args, **kwargs):
    """
    Creates a new URL by adding additional GET parameters to it.
    Quits if the parameter names clashes with the reserved names:
    'class' and 'addget'.
    """
    invalid_param_names = ('class', 'addget')
    if any((key in invalid_param_names) for key in kwargs.keys()):
        raise TemplateSyntaxError("Parameter names cannot be one of %s" %
                                  ', '.join(invalid_param_names))
    try:
        url = url.resolve({})
    except VariableDoesNotExist:
        url = url
    new_url = url
    for arg in args:
        try:
            arg = arg.resolve({})
        except VariableDoesNotExist:
            pass
        if arg:
            new_url = '%s?%s=%s' % (new_url, arg[0], conditional_escape(arg[1]))
    for key, value in kwargs.items():
        try:
            value = value.resolve({})
        except VariableDoesNotExist:
            value = value
        if value:
            new_url = '%s?%s=%s' % (new_url, key, conditional_escape(value))
    return new_url


